-- The blog moves from files in the repo into the database, so staff can write, preview, publish and delete posts
-- without a deploy. worker/index.ts serves the live columns as real HTML, so search engines see them straight away.
--
-- A post has two copies: `draft` (staff only) and the live columns. Saving only touches the draft, so a live post
-- doesn't change until someone publishes. The body is ProseMirror JSON, never HTML: src/lib/blogHtml.ts turns it into
-- HTML through an allow-list, so what is stored here can't put a script on a public page.

create table public.blog_posts (
  id uuid primary key default gen_random_uuid(),
  slug text not null unique check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$' and char_length(slug) <= 80),
  draft jsonb not null default '{}',
  draft_saved_at timestamptz not null default now(),
  is_live boolean not null default false,
  title text, seo_title text, description text, kicker text, summary text, cover_url text, cover_alt text, body jsonb, read_minutes int,
  published_at timestamptz,
  updated_at timestamptz,
  created_at timestamptz not null default now());
create index blog_posts_live_idx on public.blog_posts (published_at desc) where is_live;

alter table public.blog_posts enable row level security;
create policy "live posts are public" on public.blog_posts for select to anon, authenticated using (is_live);
-- By column: drafts stay private even on a live post. Staff read them through admin_blog_get().
grant select (id, slug, title, seo_title, description, kicker, summary, cover_url, cover_alt, body, read_minutes, published_at, updated_at)
  on public.blog_posts to anon, authenticated;

-- ---------- Images ----------
-- Public to read, staff to write. No SVG: an SVG can carry a script.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('blog-images', 'blog-images', true, 5242880, array['image/jpeg','image/png','image/webp']) on conflict (id) do nothing;
create policy "blog images staff read" on storage.objects for select to authenticated using (bucket_id = 'blog-images' and public.is_admin());
create policy "blog images staff insert" on storage.objects for insert to authenticated with check (bucket_id = 'blog-images' and public.is_admin());
create policy "blog images staff delete" on storage.objects for delete to authenticated using (bucket_id = 'blog-images' and public.is_admin());

-- ---------- What staff call ----------
create function public.blog_admin_row(p public.blog_posts) returns jsonb language sql immutable as $$
  select jsonb_build_object('id', p.id, 'slug', p.slug, 'draft', p.draft, 'draft_saved_at', p.draft_saved_at, 'is_live', p.is_live,
    'live_title', p.title, 'published_at', p.published_at, 'updated_at', p.updated_at, 'created_at', p.created_at,
    -- Compared field by field: the live columns are what the draft holds at the moment of publishing.
    'has_changes', p.is_live and p.draft is distinct from jsonb_build_object('title', p.title, 'seo_title', p.seo_title, 'description', p.description,
      'kicker', p.kicker, 'summary', p.summary, 'cover_url', p.cover_url, 'cover_alt', p.cover_alt, 'body', p.body)) $$;

create function public.admin_blog_list() returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if not public.is_admin() then raise exception 'forbidden'; end if;
  return coalesce((select jsonb_agg(public.blog_admin_row(p) #- '{draft,body}' order by p.is_live desc, coalesce(p.updated_at, p.draft_saved_at) desc) from blog_posts p), '[]');
end $$;

create function public.admin_blog_get(p_id uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if not public.is_admin() then raise exception 'forbidden'; end if;
  return (select public.blog_admin_row(p) from blog_posts p where p.id = p_id);
end $$;

-- The client picks the id, so images can be uploaded into the post's folder before its first save.
-- p_expected is the draft_saved_at it loaded: if someone else saved since, it is told rather than overwriting them.
create function public.admin_blog_save(p_id uuid, p_slug text, p_draft jsonb, p_expected timestamptz default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v blog_posts; v_clean jsonb;
begin
  if not public.is_admin() then raise exception 'forbidden'; end if;
  if p_slug !~ '^[a-z0-9]+(-[a-z0-9]+)*$' or char_length(p_slug) > 80 then raise exception 'blog_invalid_slug'; end if;
  if pg_column_size(p_draft) > 1000000 then raise exception 'blog_too_long'; end if;
  if exists (select 1 from blog_posts where slug = p_slug and id <> p_id) then raise exception 'blog_slug_taken'; end if;
  v_clean := jsonb_build_object('title', p_draft->'title', 'seo_title', p_draft->'seo_title', 'description', p_draft->'description',
    'kicker', p_draft->'kicker', 'summary', p_draft->'summary', 'cover_url', p_draft->'cover_url', 'cover_alt', p_draft->'cover_alt', 'body', p_draft->'body');
  select * into v from blog_posts where id = p_id for update;
  if not found then
    insert into blog_posts (id, slug, draft) values (p_id, p_slug, v_clean) returning * into v;
    return public.blog_admin_row(v);
  end if;
  if p_expected is not null and v.draft_saved_at > p_expected then raise exception 'blog_changed'; end if;
  -- Search engines and other sites link to it, so the address is fixed once it has been public.
  if v.published_at is not null and v.slug <> p_slug then raise exception 'blog_slug_locked'; end if;
  update blog_posts set slug = p_slug, draft = v_clean, draft_saved_at = now() where id = p_id returning * into v;
  return public.blog_admin_row(v);
end $$;

create function public.admin_blog_publish(p_id uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v blog_posts; d jsonb; v_words int;
begin
  if not public.is_admin() then raise exception 'forbidden'; end if;
  select * into v from blog_posts where id = p_id for update;
  if not found then raise exception 'blog_not_found'; end if;
  d := v.draft;
  if coalesce(trim(d->>'title'), '') = '' then raise exception 'blog_title_required'; end if;
  if v.slug like 'untitled-%' then raise exception 'blog_slug_required'; end if;
  if coalesce(trim(d->>'description'), '') = '' then raise exception 'blog_description_required'; end if;
  if coalesce(trim(d->>'summary'), '') = '' then raise exception 'blog_summary_required'; end if;
  select coalesce(sum(cardinality(regexp_split_to_array(trim(t #>> '{}'), '\s+'))), 0) into v_words from jsonb_path_query(d->'body', '$.**.text') t;
  if v_words = 0 then raise exception 'blog_body_required'; end if;
  update blog_posts set is_live = true, title = d->>'title', seo_title = d->>'seo_title', description = d->>'description', kicker = d->>'kicker',
    summary = d->>'summary', cover_url = d->>'cover_url', cover_alt = d->>'cover_alt', body = d->'body', read_minutes = greatest(1, ceil(v_words / 200.0)::int),
    published_at = coalesce(published_at, now()), updated_at = now()
  where id = p_id returning * into v;
  perform public.admin_audit('blog_publish', null, jsonb_build_object('slug', v.slug, 'title', v.title));
  return public.blog_admin_row(v);
end $$;

create function public.admin_blog_unpublish(p_id uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v blog_posts;
begin
  if not public.is_admin() then raise exception 'forbidden'; end if;
  update blog_posts set is_live = false where id = p_id returning * into v;
  if not found then raise exception 'blog_not_found'; end if;
  perform public.admin_audit('blog_unpublish', null, jsonb_build_object('slug', v.slug, 'title', v.title));
  return public.blog_admin_row(v);
end $$;

create function public.admin_blog_delete(p_id uuid) returns void
language plpgsql security definer set search_path = public as $$
declare v blog_posts;
begin
  if not public.is_admin() then raise exception 'forbidden'; end if;
  delete from blog_posts where id = p_id returning * into v;
  if not found then raise exception 'blog_not_found'; end if;
  perform public.admin_audit('blog_delete', null, jsonb_build_object('slug', v.slug, 'title', coalesce(v.title, v.draft->>'title')));
end $$;

revoke execute on function public.blog_admin_row(public.blog_posts) from public, anon, authenticated;
revoke execute on function public.admin_blog_list(), public.admin_blog_get(uuid), public.admin_blog_save(uuid, text, jsonb, timestamptz),
  public.admin_blog_publish(uuid), public.admin_blog_unpublish(uuid), public.admin_blog_delete(uuid) from public, anon;
grant execute on function public.admin_blog_list(), public.admin_blog_get(uuid), public.admin_blog_save(uuid, text, jsonb, timestamptz),
  public.admin_blog_publish(uuid), public.admin_blog_unpublish(uuid), public.admin_blog_delete(uuid) to authenticated, service_role;

-- ---------- The posts that used to be files ----------
insert into public.blog_posts (slug, draft, is_live, title, seo_title, description, kicker, summary, body, read_minutes, published_at, updated_at, created_at, draft_saved_at) values (
  'what-is-a-language-exchange', $j${"title": "What Is a Language Exchange and How Does It Work?", "seo_title": "What Is a Language Exchange?", "description": "A language exchange pairs people who help each other learn. Here is how it works, why a perfect swap is not required, and how to get the most from it.", "kicker": "Language exchange basics", "summary": "A language exchange is two people helping each other learn: you help someone with your native language, and someone helps you with theirs, though not always the same person. It is free, it gives you real conversation practice, and it works best when both partners correct each other kindly and regularly.", "body": {"type": "doc", "content": [{"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "The idea in one sentence"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "You speak English and want to learn Vietnamese. Someone else speaks Vietnamese and wants to learn English. You talk, you help each other, and nobody pays anybody. That is a language exchange, sometimes called a "}, {"type": "text", "text": "tandem", "marks": [{"type": "italic"}]}, {"type": "text", "text": "."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "It does not have to be a perfect pair. A Vietnamese speaker who is learning nothing can still help you with Vietnamese, and you can help a French speaker who is learning English, even though you speak neither French nor Vietnamese with them. Helping a learner of your language is the point, and getting help from a native speaker is the other half. They don't have to be the same person."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "It works because each person is the expert in one half of the conversation. When you are stuck, your partner knows the natural way to say it. When they are stuck, you do."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "What happens in a typical exchange"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Exchanges come in many shapes, but most follow the same rhythm:"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "You pick who to talk to.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " For example you speak English and are learning Vietnamese: you write to a native Vietnamese speaker, or help someone who is learning English. If your partner is learning your language too, you can each write in the language you are learning and correct the other."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "You write in the language you are learning.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " With a swap partner you can split a chat, one language each. Otherwise you simply write in the language you are practising and they answer however suits them."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "You correct and get corrected.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " Not every mistake, just the ones that would sound odd to a native speaker or change the meaning."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "You keep what you learn.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " A good correction is only useful if you see it again later, so write it down or save it."}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Why text chat works well"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "On The Fluency Talks, practice happens in writing. Text is easy to start, fits around work and school, and gives you time to think before you reply. It also leaves a written record, so a correction is right there to read again instead of disappearing after a call."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "If speaking feels scary, text is a perfectly good place to begin, not a lesser one. Many exchanges elsewhere add voice or video later, once partners know each other. We don't offer calls yet, and we'll say so here if that changes."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "What a language exchange is good for"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Real, everyday language.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " Textbooks teach what is correct. Native speakers teach what people actually say, including slang and idioms."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Confidence.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " Using a language with a patient person is the fastest way to stop freezing up."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Culture.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " You learn why people say things, not just what they say."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Cost.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " It is free. You pay with your time and your own language."}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "What it is not"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Your partner is not a teacher. They may not be able to explain "}, {"type": "text", "text": "why", "marks": [{"type": "italic"}]}, {"type": "text", "text": " a grammar rule works, only that something sounds right or wrong. That is fine: pair the exchange with a course, a book or an app for structure, and use the exchange for practice."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "It is also not a dating site or a social feed. The best exchanges stay focused on helping each other learn."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Who can take part"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Anyone. Complete beginners (CEFR level A1) can exchange too: write short messages, ask simple questions, and lean on your partner's corrections. Advanced learners (C1 and C2) use exchanges to polish style and sound natural. If you are not sure what the levels mean, they run from A1 (beginner) to C2 (near-native)."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "You also do not have to be a native speaker to help. A learner at an intermediate level (B1 and above) can often correct a beginner perfectly well."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "How to get the most out of it"}]}, {"type": "orderedList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Be specific about what you want.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " \"Please correct my grammar but ignore small typos\" helps your partner help you."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Show up regularly.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " Ten minutes most days beats two hours once a month."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Give as much as you take.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " The exchanges that last are the ones where both people feel helped."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Review your corrections.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " Look back at what you got wrong last week. That is where the learning sticks."}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Ready to try one? Read "}, {"type": "text", "text": "how to find a language exchange partner online", "marks": [{"type": "link", "attrs": {"href": "/blog/find-a-language-exchange-partner"}}]}, {"type": "text", "text": ", or see "}, {"type": "text", "text": "how to ask native speakers for corrections", "marks": [{"type": "link", "attrs": {"href": "/blog/corrections-from-native-speakers"}}]}, {"type": "text", "text": " without feeling awkward."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "How The Fluency Talks does it"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "On "}, {"type": "text", "text": "The Fluency Talks", "marks": [{"type": "link", "attrs": {"href": "/"}}]}, {"type": "text", "text": " you choose the language you speak and the one you are learning, and we show you every native speaker of your target language plus everyone learning yours. A perfect swap ranks first, but you never need one. You chat in writing, and your partner can correct a sentence right where you wrote it. You see exactly what changed, accept it or not, and accepted corrections go into your own phrasebook to review later. It is free, with no paid plans."}]}]}, "cover_url": null, "cover_alt": null}$j$::jsonb, true,
  $t$What Is a Language Exchange and How Does It Work?$t$, $t$What Is a Language Exchange?$t$, $t$A language exchange pairs people who help each other learn. Here is how it works, why a perfect swap is not required, and how to get the most from it.$t$, $t$Language exchange basics$t$, $t$A language exchange is two people helping each other learn: you help someone with your native language, and someone helps you with theirs, though not always the same person. It is free, it gives you real conversation practice, and it works best when both partners correct each other kindly and regularly.$t$,
