insert into public.blog_posts (slug, draft, is_live, title, seo_title, description, kicker, summary, body, read_minutes, published_at, updated_at, created_at, draft_saved_at) values (
  'corrections-from-native-speakers', $j${"title": "How to Get Corrections from Native Speakers Without Feeling Embarrassed", "seo_title": "How to Get Corrected by Native Speakers", "description": "Corrections are how you go from understandable to natural. How to ask native speakers to correct you, what kind of feedback to ask for, and how to remember it.", "kicker": "Speaking confidence", "summary": "Native speakers often will not correct you unless you ask, because they do not want to be rude. Tell them clearly that you want corrections, say which kind (meaning, grammar, or sounding natural), and save each correction so you review it later. Mistakes are the material you learn from, not something to hide.", "body": {"type": "doc", "content": [{"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Why nobody corrects you"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "If you have chatted with native speakers and nobody ever pointed out a mistake, it is not because you made none. Most people are polite. They understood you, so correcting you feels like interrupting, or like showing off."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "That means the first step is on you: "}, {"type": "text", "text": "give people permission", "marks": [{"type": "bold"}]}, {"type": "text", "text": "."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "How to ask"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Be direct and specific. Something like:"}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Please correct me when something sounds unnatural, even if you understood it. I'd rather learn the natural way to say it."}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Write it in the language you are learning if you can. Then repeat it now and then, because people forget, and thank them every time they do it. A thank-you is the best way to get more corrections."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Ask for the right kind of correction"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Not all corrections are equal. It helps to say which matter most to you right now:"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Meaning:", "marks": [{"type": "bold"}]}, {"type": "text", "text": " did I say what I meant? This matters most for beginners."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Grammar:", "marks": [{"type": "bold"}]}, {"type": "text", "text": " verb forms, word order, gender, articles."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Sounding natural:", "marks": [{"type": "bold"}]}, {"type": "text", "text": " the sentence is correct, but no native speaker would put it that way. This is where intermediate and advanced learners grow fastest."}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Here is a classic example for English speakers learning Vietnamese. A learner wants to say \"I am hungry\" and writes "}, {"type": "text", "text": "\"Tôi là đói\"", "marks": [{"type": "italic"}, {"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": ", translating \"am\" as "}, {"type": "text", "text": "là", "marks": [{"type": "italic"}, {"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": ". It is understandable, but a native speaker would say "}, {"type": "text", "text": "\"Tôi đói\"", "marks": [{"type": "italic"}, {"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": ". In Vietnamese, words like \"hungry\" work like verbs, so they need no \"to be\"; "}, {"type": "text", "text": "là", "marks": [{"type": "italic"}, {"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " joins two nouns, as in "}, {"type": "text", "text": "\"Tôi là sinh viên\"", "marks": [{"type": "italic"}, {"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": " (\"I am a student\"). One small correction teaches a pattern you will use for tired ("}, {"type": "text", "text": "Tôi mệt", "marks": [{"type": "italic"}, {"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": "), busy ("}, {"type": "text", "text": "Tôi bận", "marks": [{"type": "italic"}, {"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": ") and happy ("}, {"type": "text", "text": "Tôi vui", "marks": [{"type": "italic"}, {"type": "lang", "attrs": {"lang": "vi"}}]}, {"type": "text", "text": ") as well."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Make corrections easy to give"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Your partner is busy too. Make it easy for them:"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Write in short messages, so a correction fits one idea."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Mark the sentence you are unsure about: \"Is this right?\""}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Do not ask them to fix a long essay. Ask about three sentences you care about."}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Dealing with the embarrassment"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Every correction proves you are doing the hard part: using the language for real. A few things help:"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Remember they are people too.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " Your partner may be learning your language and making mistakes in it. Either way, you are on the same side."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Correct others, kindly.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " When you help someone with your own language, corrections stop feeling like a judgement."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Separate the mistake from yourself.", "marks": [{"type": "bold"}]}, {"type": "text", "text": " \"That sentence was wrong\" is not \"I am bad at this\"."}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Keep what you learn"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "A correction you read once and never see again is mostly lost. Write each one down with the wrong and the right version side by side, add an example or a picture if it helps you remember, and look back over the list once a week. Patterns appear quickly: you will notice you always get the same preposition wrong, and then you will stop."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "How corrections work on The Fluency Talks"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "On "}, {"type": "text", "text": "The Fluency Talks", "marks": [{"type": "link", "attrs": {"href": "/"}}]}, {"type": "text", "text": ", correcting is built into the chat. A native speaker, or a learner at B1 or above, edits your sentence right where you wrote it. You see what you wrote in red and the correction in green, and you choose whether to accept it. Accepted corrections are saved to your personal phrasebook, so reviewing them is one tap away."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "People who correct you earn 5 points for each correction you accept, so helping is rewarded. And if you are stuck on a question, you can spend 50 points on a bounty to show it to people who know the language. The helper gets the 50 points when you accept their answer; if you accept none within 48 hours, you get them back."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Still looking for someone to practise with? Here is "}, {"type": "text", "text": "how to find a language exchange partner online", "marks": [{"type": "link", "attrs": {"href": "/blog/find-a-language-exchange-partner"}}]}, {"type": "text", "text": ", or "}, {"type": "text", "text": "sign up free", "marks": [{"type": "link", "attrs": {"href": "/signup"}}]}, {"type": "text", "text": " and get matched today."}]}]}, "cover_url": null, "cover_alt": null}$j$::jsonb, true,
  $t$How to Get Corrections from Native Speakers Without Feeling Embarrassed$t$, $t$How to Get Corrected by Native Speakers$t$, $t$Corrections are how you go from understandable to natural. How to ask native speakers to correct you, what kind of feedback to ask for, and how to remember it.$t$, $t$Speaking confidence$t$, $t$Native speakers often will not correct you unless you ask, because they do not want to be rude. Tell them clearly that you want corrections, say which kind (meaning, grammar, or sounding natural), and save each correction so you review it later. Mistakes are the material you learn from, not something to hide.$t$,
